
import { useState } from "react";
import {
  MapPin,
  Users,
  Building2,
  TrendingUp,
  Activity,
  ArrowRight,
  BrainCircuit,
  Info,
  RotateCcw,
  Loader2,
  AlertCircle,
  CheckCircle2,
  Sparkles,
  SlidersHorizontal,
  ChevronDown,
} from "lucide-react";

const API_BASE = "http://127.0.0.1:8002/api/scenario";

// Clean inconsistent Markdown generated by AI
const cleanMarkdownLine = (line) => {
  let cleaned = String(line)
    .replace(/\r/g, "")
    .replace(/\\\*/g, "*")
    .replace(/\\_/g, "_")
    .trim();

  if (/^[•·▪●*-]+$/.test(cleaned)) {
    return "";
  }

  cleaned = cleaned.replace(/^\*([^*]+):\*\*$/, "**$1:**");
  cleaned = cleaned.replace(/^\*([^*]+)\*\*$/, "**$1**");
  cleaned = cleaned.replace(/^\*\*([^*]+)\*$/, "**$1**");

  return cleaned;
};

// Format inline Markdown and render bold text properly
const formatInlineText = (text) => {
  const cleaned = String(text)
    .replace(/\\\*/g, "*")
    .replace(/\\_/g, "_");

  const parts = cleaned.split(/(\*\*.*?\*\*)/g);

  return parts.map((part, index) => {
    if (part.startsWith("**") && part.endsWith("**")) {
      return (
        <strong
          key={index}
          className="font-semibold text-[#40566b]"
        >
          {part.slice(2, -2)}
        </strong>
      );
    }

    return part;
  });
};

// Properly formatted AI insights
function FormattedInsights({ content }) {
  if (!content) return null;

  const lines = String(content)
    .replace(/\r/g, "")
    .split("\n")
    .map(cleanMarkdownLine)
    .filter(Boolean);

  let sectionCount = 0;

  return (
    <div className="text-sm leading-7 text-[#625d6c]">
      {lines.map((line, index) => {
        // Main document title
        if (/^#{1,2}\s+/.test(line)) {
          return (
            <h2
              key={index}
              className="text-lg md:text-xl font-semibold text-[#344e68] mb-5 leading-snug"
            >
              {formatInlineText(line.replace(/^#{1,2}\s+/, ""))}
            </h2>
          );
        }

        // Numbered main sections
        const sectionHeading = line.match(
          /^#{0,6}\s*(\d+)\.\s+(.+)$/
        );

        if (sectionHeading) {
          sectionCount++;

          return (
            <h3
              key={index}
              className={`text-base md:text-lg font-semibold text-[#344e68] pb-3 ${
                sectionCount === 1
                  ? "pt-2"
                  : "mt-8 pt-6 border-t border-[#e8e4ed]"
              }`}
            >
              <span className="text-[#82968a] mr-1">
                {sectionHeading[1]}.
              </span>
              {formatInlineText(sectionHeading[2])}
            </h3>
          );
        }

        // Smaller Markdown headings
        if (/^#{3,6}\s+/.test(line)) {
          return (
            <h4
              key={index}
              className="text-sm font-semibold text-[#40566b] mt-5 mb-2"
            >
              {formatInlineText(line.replace(/^#{3,6}\s+/, ""))}
            </h4>
          );
        }

        // Bold-only subheadings
        const subheading = line.match(/^\*\*(.*?)\*\*$/);

        if (subheading) {
          return (
            <h4
              key={index}
              className="font-semibold text-[#40566b] mt-4 mb-2"
            >
              {subheading[1]}
            </h4>
          );
        }

        // Bullet points
        const bullet = line.match(/^[-*•·▪●]\s+(.+)$/);

        if (bullet) {
          return (
            <div
              key={index}
              className="flex items-start gap-3 pl-5 md:pl-7 mb-2"
            >
              <span className="text-[#82968a] font-bold shrink-0 mt-[1px]">
                •
              </span>

              <p className="flex-1 min-w-0 leading-7">
                {formatInlineText(bullet[1])}
              </p>
            </div>
          );
        }

        // Numbered sub-points
        const numberedPoint = line.match(/^(\d+)\.\s+(.+)$/);

        if (numberedPoint) {
          return (
            <div
              key={index}
              className="flex items-start gap-3 pl-5 md:pl-7 mb-2"
            >
              <span className="text-[#82968a] font-semibold shrink-0">
                {numberedPoint[1]}.
              </span>

              <p className="flex-1 min-w-0 leading-7">
                {formatInlineText(numberedPoint[2])}
              </p>
            </div>
          );
        }

        // Normal paragraphs
        return (
          <p key={index} className="mb-3 leading-7">
            {formatInlineText(line)}
          </p>
        );
      })}
    </div>
  );
}

function ScenarioPlanning({
  studyArea = "Karnataka",
  districts = [],
  taluks = [],
  selectedDistrict,
  selectedDistrictCode = "",
  selectedTaluk = "",
  onDistrictChange = () => {},
  onTalukChange = () => {},
}) {
  const [growth, setGrowth] = useState(15);
  const [facility, setFacility] = useState("Hospital");
  const [facilityCount, setFacilityCount] = useState(2);

  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);
  const [aiLoading, setAiLoading] = useState(false);

  const [error, setError] = useState("");
  const [aiError, setAiError] = useState("");

  const filteredTaluks = taluks
    .filter(
      (taluk) =>
        String(taluk.properties?.KGISDistri) ===
        String(selectedDistrictCode)
    )
    .sort((a, b) =>
      String(a.properties?.KGISTalukN || "").localeCompare(
        String(b.properties?.KGISTalukN || "")
      )
    );

  // Clear old results whenever scenario inputs change
  const clearPreviousResult = () => {
    setResult(null);
    setError("");
    setAiError("");
  };

  const handleDistrictChange = (e) => {
    onDistrictChange(e.target.value);
    clearPreviousResult();
  };

  const handleTalukChange = (e) => {
    onTalukChange(e.target.value);
    clearPreviousResult();
  };

  // Reset scenario inputs and results
  const handleReset = () => {
    setGrowth(15);
    setFacility("Hospital");
    setFacilityCount(2);
    setResult(null);
    setError("");
    setAiError("");
  };

  // Calculate scenario and request AI insights
  const calculateScenario = async () => {
    if (!selectedDistrictCode) {
      setError("Please select a district first.");
      return;
    }

    if (!facilityCount || facilityCount < 1) {
      setError("Please enter at least one proposed facility.");
      return;
    }

    setLoading(true);
    setError("");
    setAiError("");
    setResult(null);

    const scenarioPayload = {
      study_area: studyArea,
      growth_rate: growth,
      facility_type: facility,
      facility_count: Number(facilityCount),
    };

    try {
      // STEP 1: Backend scenario calculation
      const response = await fetch(`${API_BASE}/calculate`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(scenarioPayload),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(
          typeof data.detail === "string"
            ? data.detail
            : "Unable to calculate the scenario."
        );
      }

      setResult(data);

      // STEP 2: Generate AI planning insights
      setAiLoading(true);

      try {
        const aiResponse = await fetch(`${API_BASE}/insights`, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify(scenarioPayload),
        });

        const aiData = await aiResponse.json();

        if (!aiResponse.ok) {
          throw new Error(
            typeof aiData.detail === "string"
              ? aiData.detail
              : "Unable to generate AI insights."
          );
        }

        if (!aiData.insights) {
          throw new Error("The AI endpoint returned no insights.");
        }

        setResult((previous) => ({
          ...previous,
          insights: aiData.insights,
        }));
      } catch (aiErr) {
        console.error("AI insights error:", aiErr);
        setAiError(aiErr.message);
      } finally {
        setAiLoading(false);
      }
    } catch (err) {
      console.error("Scenario calculation error:", err);

      setError(
        err.message === "Failed to fetch"
          ? "Cannot connect to METRIX backend. Make sure FastAPI is running on port 8002."
          : err.message
      );
    } finally {
      setLoading(false);
    }
  };

  // Backend result sections
  const scenario = result?.scenario;
  const interpretation = result?.interpretation;

  // Calculate multiplier if backend does not provide one
  const growthRate = Number(scenario?.growth_rate ?? growth);

  const growthMultiplier = Number(
    scenario?.growth_multiplier ?? 1 + growthRate / 100
  );

  return (
    <div className="space-y-7 text-[#34465a]">
      {/* INTRODUCTION */}
      <section>
        <div className="flex items-center gap-2 text-xs font-semibold uppercase tracking-[0.16em] text-[#82968a] mb-3">
          <Activity size={14} />
          METRIX intelligence
        </div>

        <h1 className="serif-heading text-3xl md:text-4xl text-[#243b53]">
          What-If Scenario Planning
        </h1>

        <p className="text-sm text-[#87929c] mt-2 max-w-2xl leading-6">
          Explore hypothetical urban growth and infrastructure decisions.
          Understand possible implications before planning for tomorrow's city.
        </p>
      </section>

      {/* STUDY AREA */}
      <section className="bg-[#e8edf3] border border-[#dfe6ee] rounded-2xl p-5">
        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-5">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 rounded-xl bg-white/80 text-[#607d99] flex items-center justify-center shrink-0">
              <MapPin size={22} />
            </div>

            <div>
              <p className="text-xs font-medium text-[#7e91a2]">
                CURRENT STUDY AREA
              </p>

              <h3 className="text-lg font-semibold text-[#344e68] mt-1">
                {selectedTaluk ||
                  selectedDistrict?.properties?.KGISDist_1 ||
                  studyArea}
                , Karnataka
              </h3>

              <p className="text-xs text-[#8194a7] mt-1">
                Choose a district and optionally narrow down to a taluk.
              </p>
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 w-full lg:max-w-[490px]">
            <div>
              <label className="block text-[11px] font-semibold tracking-wide text-[#71869b] mb-2">
                SELECT DISTRICT
              </label>

              <div className="relative">
                <select
                  value={selectedDistrictCode}
                  onChange={handleDistrictChange}
                  disabled={districts.length === 0}
                  className="w-full appearance-none bg-white border border-[#dfe6ee] rounded-xl px-3 py-3 pr-9 text-sm font-medium text-[#40566b] outline-none focus:ring-2 focus:ring-[#cbd9e6] disabled:opacity-60"
                >
                  {districts.length === 0 && (
                    <option value="">Loading districts...</option>
                  )}

                  {districts.map((district) => (
                    <option
                      key={district.properties.KGISDistri}
                      value={String(district.properties.KGISDistri)}
                    >
                      {district.properties.KGISDist_1}
                    </option>
                  ))}
                </select>

                <ChevronDown
                  size={16}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-[#82909c] pointer-events-none"
                />
              </div>
            </div>

            <div>
              <label className="block text-[11px] font-semibold tracking-wide text-[#71869b] mb-2">
                SELECT TALUK
              </label>

              <div className="relative">
                <select
                  value={selectedTaluk}
                  onChange={handleTalukChange}
                  disabled={!selectedDistrictCode || filteredTaluks.length === 0}
                  className="w-full appearance-none bg-white border border-[#dfe6ee] rounded-xl px-3 py-3 pr-9 text-sm font-medium text-[#40566b] outline-none focus:ring-2 focus:ring-[#cbd9e6] disabled:opacity-60"
                >
                  <option value="">All taluks in district</option>

                  {filteredTaluks.map((taluk) => (
                    <option
                      key={taluk.properties.KGISTalukC}
                      value={taluk.properties.KGISTalukN}
                    >
                      {taluk.properties.KGISTalukN}
                    </option>
                  ))}
                </select>

                <ChevronDown
                  size={16}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-[#82909c] pointer-events-none"
                />
              </div>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-2 text-xs text-[#617c70] bg-white/70 rounded-full px-3 py-2 w-fit mt-4">
          <span className="w-2 h-2 rounded-full bg-[#82a18a]" />
          Scenario workspace
        </div>
      </section>

      {/* CONFIGURATION INTRO */}
      <section>
        <div className="flex items-center gap-2 text-xs font-semibold uppercase tracking-wider text-[#91a095] mb-2">
          <SlidersHorizontal size={14} />
          Configure your scenario
        </div>

        <h2 className="serif-heading text-2xl text-[#243b53]">
          What should the future look like?
        </h2>

        <p className="text-xs text-[#929ca4] mt-1">
          Adjust the assumptions below to explore a possible development scenario.
        </p>
      </section>

      {/* INPUT CARDS */}
      <section className="grid grid-cols-1 xl:grid-cols-2 gap-5">
        {/* POPULATION GROWTH */}
        <div className="bg-white border border-[#e9e8e2] rounded-[22px] p-6 shadow-sm">
          <div className="flex items-center gap-3 mb-7">
            <div className="w-11 h-11 rounded-xl bg-[#e8edf3] text-[#657f98] flex items-center justify-center">
              <Users size={21} />
            </div>

            <div>
              <h3 className="font-semibold text-[#344e68]">
                Population Growth
              </h3>
              <p className="text-xs text-[#9aa3a9] mt-1">
                Adjust the hypothetical growth assumption
              </p>
            </div>
          </div>

          <div className="flex items-end justify-between gap-3 mb-4">
            <label className="text-sm text-[#71808c]">Growth rate</label>

            <span className="text-3xl font-semibold text-[#526f8d] tabular-nums">
              {growth}%
            </span>
          </div>

          <input
            type="range"
            min="0"
            max="100"
            step="1"
            value={growth}
            onChange={(e) => {
              setGrowth(Number(e.target.value));
              clearPreviousResult();
            }}
            className="w-full accent-[#607d99] cursor-pointer"
          />

          <div className="flex justify-between text-[11px] text-[#a2abb0] mt-2">
            <span>0%</span>
            <span>25%</span>
            <span>50%</span>
            <span>75%</span>
            <span>100%</span>
          </div>

          <div className="mt-7 p-4 rounded-xl bg-[#f2f5f2] border border-[#e8eee8]">
            <div className="flex items-start gap-2">
              <Info size={15} className="text-[#819b87] shrink-0 mt-0.5" />
              <p className="text-xs text-[#788d7e] leading-5">
                This percentage is a user-defined hypothetical assumption,
                not an official population forecast.
              </p>
            </div>
          </div>
        </div>

        {/* INFRASTRUCTURE */}
        <div className="bg-white border border-[#e9e8e2] rounded-[22px] p-6 shadow-sm">
          <div className="flex items-center gap-3 mb-7">
            <div className="w-11 h-11 rounded-xl bg-[#eeeaf4] text-[#81739d] flex items-center justify-center">
              <Building2 size={21} />
            </div>

            <div>
              <h3 className="font-semibold text-[#344e68]">
                Proposed Infrastructure
              </h3>
              <p className="text-xs text-[#9aa3a9] mt-1">
                Simulate a proposed facility addition
              </p>
            </div>
          </div>

          <label className="block text-xs font-semibold text-[#758493] mb-2">
            FACILITY TYPE
          </label>

          <select
            value={facility}
            onChange={(e) => {
              setFacility(e.target.value);
              clearPreviousResult();
            }}
            className="w-full bg-[#f8f7f3] border border-[#e9e8e2] rounded-xl px-4 py-3.5 text-sm text-[#40566b] outline-none focus:ring-2 focus:ring-[#dce8e2]"
          >
            <option value="Hospital">Hospital</option>
            <option value="Primary Health Centre">Primary Health Centre</option>
            <option value="School">School</option>
            <option value="College">College</option>
            <option value="Water Facility">Water Facility</option>
          </select>

          <label className="block text-xs font-semibold text-[#758493] mt-5 mb-2">
            NUMBER OF PROPOSED FACILITIES
          </label>

          <input
            type="number"
            min="1"
            max="100"
            value={facilityCount}
            onChange={(e) => {
              const value = e.target.value;

              setFacilityCount(
                value === ""
                  ? ""
                  : Math.max(1, Math.min(100, Number(value)))
              );

              clearPreviousResult();
            }}
            onBlur={() => {
              if (!facilityCount || facilityCount < 1) {
                setFacilityCount(1);
              }
            }}
            className="w-full bg-[#f8f7f3] border border-[#e9e8e2] rounded-xl px-4 py-3.5 text-sm text-[#40566b] outline-none focus:ring-2 focus:ring-[#dce8e2]"
          />

          <p className="text-[11px] text-[#a1a9ae] mt-2">
            Enter a value between 1 and 100.
          </p>
        </div>
      </section>

      {/* SCENARIO PREVIEW */}
      <section className="bg-white border border-[#e9e8e2] rounded-[22px] p-6 shadow-sm">
        <div className="flex items-center gap-3 mb-5">
          <div className="w-10 h-10 rounded-xl bg-[#e8eee9] text-[#718d79] flex items-center justify-center">
            <Activity size={19} />
          </div>

          <div>
            <h3 className="font-semibold text-[#344e68]">
              Scenario Preview
            </h3>
            <p className="text-xs text-[#9aa3a9] mt-1">
              Review your assumptions before calculation
            </p>
          </div>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
          <div className="bg-[#f8f7f3] rounded-xl p-4 border border-[#eeede7]">
            <p className="text-xs text-[#9aa3a9]">Study area</p>
            <p className="text-sm font-semibold text-[#40566b] mt-2">
              {studyArea}
            </p>
          </div>

          <div className="bg-[#f8f7f3] rounded-xl p-4 border border-[#eeede7]">
            <p className="text-xs text-[#9aa3a9]">Growth assumption</p>
            <p className="text-sm font-semibold text-[#526f8d] mt-2">
              +{growth}%
            </p>
          </div>

          <div className="bg-[#f8f7f3] rounded-xl p-4 border border-[#eeede7]">
            <p className="text-xs text-[#9aa3a9]">Proposed development</p>
            <p className="text-sm font-semibold text-[#65577f] mt-2">
              {facilityCount || 0} {facility}
              {facilityCount > 1 ? "s" : ""}
            </p>
          </div>
        </div>

        <div className="flex flex-col sm:flex-row gap-3 mt-6">
          <button
            onClick={calculateScenario}
            disabled={
              loading ||
              !facilityCount ||
              facilityCount < 1 ||
              !selectedDistrictCode
            }
            className="flex-1 flex items-center justify-center gap-2 bg-[#344e68] hover:bg-[#243b53] disabled:bg-[#aab7c2] text-white rounded-xl py-3.5 px-5 text-sm font-semibold transition-all"
          >
            {loading ? (
              <>
                <Loader2 size={17} className="animate-spin" />
                Calculating scenario...
              </>
            ) : (
              <>
                Calculate Scenario
                <ArrowRight size={17} />
              </>
            )}
          </button>

          <button
            onClick={handleReset}
            disabled={loading}
            className="flex items-center justify-center gap-2 border border-[#e6e6df] hover:bg-[#f8f7f3] disabled:opacity-50 text-[#71808c] rounded-xl py-3.5 px-5 text-sm font-medium transition"
          >
            <RotateCcw size={16} />
            Reset
          </button>
        </div>
      </section>

      {/* CALCULATION ERROR */}
      {error && (
        <div className="bg-[#f8eeec] border border-[#f0ddda] rounded-xl p-4 flex gap-3">
          <AlertCircle size={19} className="text-[#b46d63] shrink-0" />
          <div>
            <p className="font-semibold text-[#985e55] text-sm">
              Calculation failed
            </p>
            <p className="text-xs text-[#a56d65] mt-1">{error}</p>
          </div>
        </div>
      )}

      {/* RESULTS */}
      {result && (
        <section className="space-y-5">
          <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-3">
            <div>
              <div className="flex items-center gap-2 text-xs font-semibold uppercase tracking-wider text-[#82968a] mb-2">
                <TrendingUp size={14} />
                Analysis output
              </div>

              <h2 className="serif-heading text-2xl text-[#243b53]">
                Your Scenario Results
              </h2>

              <p className="text-xs text-[#929ca4] mt-1">
                Backend calculation and AI-assisted interpretation
              </p>
            </div>

            <div className="flex items-center gap-2 text-xs text-[#64816d] bg-[#eaf1eb] rounded-full px-3 py-2 w-fit">
              <CheckCircle2 size={14} />
              Calculation successful
            </div>
          </div>

          {/* METRICS */}
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
            <div className="bg-[#e8edf3] border border-[#dfe6ee] rounded-2xl p-5">
              <div className="flex items-center justify-between">
                <p className="text-xs text-[#71869b]">Growth assumption</p>
                <Users size={18} className="text-[#718ba4]" />
              </div>

              <h3 className="text-3xl font-semibold text-[#405d78] mt-3">
                +{growthRate}%
              </h3>

              <p className="text-[11px] text-[#8194a7] mt-1">
                Hypothetical input
              </p>
            </div>

            <div className="bg-[#eeeaf4] border border-[#e5dfee] rounded-2xl p-5">
              <div className="flex items-center justify-between">
                <p className="text-xs text-[#887c9e]">Growth multiplier</p>
                <TrendingUp size={18} className="text-[#897ba4]" />
              </div>

              <h3 className="text-3xl font-semibold text-[#65577f] mt-3">
                {Number.isFinite(growthMultiplier)
                  ? `${growthMultiplier.toFixed(2)}×`
                  : "—"}
              </h3>

              <p className="text-[11px] text-[#968ba9] mt-1">
                Calculated from the growth assumption
              </p>
            </div>

            <div className="bg-[#e8eee9] border border-[#dfe8e1] rounded-2xl p-5">
              <div className="flex items-center justify-between">
                <p className="text-xs text-[#71877b]">Proposed facilities</p>
                <Building2 size={18} className="text-[#718d79]" />
              </div>

              <h3 className="text-3xl font-semibold text-[#405d50] mt-3">
                {scenario?.facility_count ?? facilityCount}
              </h3>

              <p className="text-[11px] text-[#81958a] mt-1">
                {scenario?.facility_type ?? facility}
              </p>
            </div>
          </div>

          {/* SCENARIO INTERPRETATION */}
          {interpretation && (
            <div className="bg-white border border-[#e9e8e2] rounded-[22px] p-6 shadow-sm">
              <h3 className="serif-heading text-xl text-[#344e68]">
                Scenario Interpretation
              </h3>

              <p className="text-xs text-[#9aa3a9] mt-1 mb-5">
                What these assumptions could mean for planning
              </p>

              <div className="space-y-3">
                {interpretation.population && (
                  <div className="bg-[#f1f5f7] rounded-xl p-4 border border-[#e7edf0]">
                    <div className="flex items-center gap-2 mb-2">
                      <Users size={16} className="text-[#6e879d]" />
                      <p className="text-xs font-semibold text-[#526f85]">
                        Population scenario
                      </p>
                    </div>

                    <p className="text-sm text-[#647787] leading-6">
                      {interpretation.population}
                    </p>
                  </div>
                )}

                {interpretation.infrastructure && (
                  <div className="bg-[#f1f4f0] rounded-xl p-4 border border-[#e6ece5]">
                    <div className="flex items-center gap-2 mb-2">
                      <Building2 size={16} className="text-[#76917b]" />
                      <p className="text-xs font-semibold text-[#58715e]">
                        Infrastructure scenario
                      </p>
                    </div>

                    <p className="text-sm text-[#6e8172] leading-6">
                      {interpretation.infrastructure}
                    </p>
                  </div>
                )}
              </div>
            </div>
          )}

          {/* AI INSIGHTS */}
          <div className="bg-white border border-[#e5e2ec] rounded-[22px] p-5 md:p-6 shadow-sm">
            <div className="flex items-center gap-3 mb-5">
              <div className="w-11 h-11 rounded-xl bg-[#eeeaf4] text-[#81739d] flex items-center justify-center">
                <BrainCircuit size={22} />
              </div>

              <div>
                <h3 className="font-semibold text-[#344e68]">
                  AI Planning Insights
                </h3>
                <p className="text-xs text-[#9a94aa] mt-1">
                  AI-assisted scenario interpretation
                </p>
              </div>

              <Sparkles size={19} className="text-[#a294bd] ml-auto" />
            </div>

            {aiLoading && (
              <div className="flex items-center gap-3 bg-[#f4f1f8] rounded-xl p-5 text-[#77688f]">
                <Loader2 size={19} className="animate-spin shrink-0" />
                <div>
                  <p className="text-sm font-semibold">
                    Analysing your scenario...
                  </p>
                  <p className="text-xs mt-1 text-[#978ca8]">
                    Generating possible implications and planning considerations.
                  </p>
                </div>
              </div>
            )}

            {aiError && (
              <div className="bg-[#f8eeec] border border-[#f0ddda] rounded-xl p-4">
                <p className="text-sm font-semibold text-[#985e55]">
                  AI insights unavailable
                </p>

                <p className="text-xs text-[#a56d65] mt-1">{aiError}</p>

                <p className="text-xs text-[#a56d65] mt-2">
                  The backend scenario calculation is still available above.
                </p>
              </div>
            )}

            {result.insights && (
              <div className="bg-[#f7f5f9] border border-[#eeebf3] rounded-xl p-5 md:p-6">
                <FormattedInsights content={result.insights} />
              </div>
            )}

            {!aiLoading && !aiError && !result.insights && (
              <p className="text-sm text-[#92909a]">
                Waiting for AI-generated planning insights...
              </p>
            )}

            <p className="text-[11px] text-[#a29caa] mt-4 leading-5">
              AI output is an exploratory interpretation of user-defined
              assumptions. It is not a validated urban forecast or a substitute
              for verified local planning data.
            </p>
          </div>
        </section>
      )}
    </div>
  );
}

export default ScenarioPlanning;
